(() => {
'use strict';
const $=s=>document.querySelector(s), core=window.LinearLesson;
const signs={lt:'<',le:'\\le',gt:'>',ge:'\\ge'};
function math(host,tex){const el=document.createElement('span');el.dataset.tex=tex;host.replaceChildren(el);}
function holds(x,relation,bound){return relation==='lt'?x<bound:relation==='le'?x<=bound:relation==='gt'?x>bound:x>=bound;}
function renderLine(){const r=$('input[name="relation"]:checked').value,x=Number($('#candidate').value),left=r==='lt'||r==='le',closed=r==='le'||r==='ge';$('#candidate-out').value=x;$('#ray').className='ray '+(left?'left':'right');$('#ray').style.left=left?'0':'75%';$('#ray').style.width=left?'75%':'25%';$('#endpoint').className='endpoint'+(closed?' closed':'');$('#probe').style.left=((x+4)/8*100)+'%';$('#line-description').textContent=(left?'Daerah solusi menuju kiri. ':'Daerah solusi menuju kanan. ')+(closed?'Batas dua ikut memenuhi (lingkaran penuh).':'Batas dua tidak memenuhi (lingkaran kosong).');math($('#candidate-equation'),`${x}${signs[r]}2`);$('#candidate-feedback').textContent=holds(x,r,2)?'Pernyataan benar. Nilai yang kamu coba termasuk himpunan solusi.':'Pernyataan salah. Nilai yang kamu coba tidak termasuk himpunan solusi.';}
$('#candidate').addEventListener('input',renderLine);document.querySelectorAll('[name="relation"]').forEach(e=>e.addEventListener('change',renderLine));renderLine();
function multiply(m){math($('#multiply-result'),m===0?'2\\times0=5\\times0=0':`2\\times(${m})${m<0?'>':'<'}5\\times(${m})\\quad\\Rightarrow\\quad${2*m}${m<0?'>':'<'}${5*m}`);$('#multiply-feedback').textContent=m===0?'Keduanya menjadi nol. Urutan semula hilang: kita tidak bisa mengembalikan pertidaksamaan awal dengan membagi nol.':m<0?'Tanda berbalik. Negatif empat lebih besar dari negatif sepuluh: posisinya lebih ke kanan.':'Tanda tetap. Empat masih lebih kecil dari sepuluh.';}
document.querySelectorAll('[data-multiplier]').forEach(b=>b.addEventListener('click',()=>multiply(Number(b.dataset.multiplier))));multiply(2);
const questions=[
{tex:'x+2<5',r:'lt',n:3,d:1,hint:'Kurangi kedua ruas dengan dua.',why:'Setelah kedua ruas dikurangi dua, diperoleh x lebih kecil dari tiga. Tiga sendiri tidak memenuhi.'},
{tex:'3x\\le12',r:'le',n:4,d:1,hint:'Bagi kedua ruas dengan tiga. Pembagi positif menjaga tanda.',why:'Bagi kedua ruas dengan tiga: x lebih kecil dari atau sama dengan empat. Batas empat ikut memenuhi.'},
{tex:'-2x+3<11',r:'gt',n:-4,d:1,hint:'Kurangi tiga, lalu bagi dengan negatif dua. Perhatikan arah tandanya.',why:'Diperoleh negatif dua kali x lebih kecil dari delapan. Setelah dibagi negatif dua, x lebih besar dari negatif empat.'},
{tex:'5-x\\ge2',r:'le',n:3,d:1,hint:'Kurangi lima, lalu bagi dengan negatif satu.',why:'Negatif x lebih besar dari atau sama dengan negatif tiga. Membagi dengan negatif satu memberi x lebih kecil dari atau sama dengan tiga.'},
{tex:'2x+1>2',r:'gt',n:1,d:2,hint:'Kurangi satu, lalu bagi dengan dua.',why:'Diperoleh dua kali x lebih besar dari satu, jadi x lebih besar dari setengah.'},
{tex:'2(x-1)\\le x+3',r:'le',n:5,d:1,hint:'Buka kurung, kurangi x pada kedua ruas, lalu tambahkan dua.',why:'Dua kali x dikurangi dua lebih kecil dari atau sama dengan x ditambah tiga. Setelah disederhanakan, x lebih kecil dari atau sama dengan lima.'}
];
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p>Selesaikan <span data-tex="${q.tex}"></span>.</p><form data-question="${i}"><fieldset><legend>Tanda untuk jawabanmu (variabel di kiri)</legend><div class="answer-relation">${Object.keys(signs).map(r=>`<label><input type="radio" name="answer-relation-${i}" value="${r}" required aria-label="${({lt:'lebih kecil dari',le:'lebih kecil dari atau sama dengan',gt:'lebih besar dari',ge:'lebih besar dari atau sama dengan'})[r]}"><span data-tex="x${signs[r]} b"></span></label>`).join('')}</div></fieldset><label for="answer${i}">Nilai batas (b)</label><div class="answer-line"><input id="answer${i}" type="text" autocomplete="off" required aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');
const solved=new Set();document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=core.parseAnswer($('#answer'+i).value),r=form.querySelector('input:checked').value,ok=core.equalAnswer(a,core.rational(q.n,q.d))&&r===q.r,fb=$('#feedback'+i);fb.className='feedback '+(ok?'correct':'incorrect');fb.textContent=ok?'Tepat. '+q.why:!a?'Tulis satu bilangan untuk batas, misalnya -4 atau 1/2.':core.equalAnswer(a,core.rational(q.n,q.d))?'Nilai batas sudah tepat. Periksa arah tanda dan apakah batas ikut memenuhi.':'Belum tepat. Periksa operasi pada kedua ruas dan nilai batasnya.';if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari ${questions.length} latihan sudah dijawab tepat.`;}));
const storage={get(k){try{return localStorage.getItem('fondasi-inequality-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-inequality-'+k,v);return true}catch{return false}}};
$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan. Salin jika ingin menyimpannya.';});
function completed(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}
$('#complete').addEventListener('click',()=>completed(storage.set('complete','yes')));if(storage.get('complete')==='yes')completed(true);
})();
